package com.ledgerbase.backend.model;

import java.time.OffsetDateTime;

/**
 * Represents an audit event in LedgerBase.
 *
 * Maps to the PostgreSQL audit_events table.
 *
 * Audit events record important financial actions,
 * such as creating or posting a transaction.
 *
 * Each event identifies:
 * - The business affected
 * - The user who performed the action
 * - The action performed
 * - The entity affected
 * - Optional JSON details
 * - The time of the event
 */
public class AuditEvent {

    // Unique audit event ID generated by PostgreSQL.
    private Long id;

    // Business associated with the event.
    private Long businessId;

    // User responsible for performing the action.
    private Long actorId;

    // Action name, e.g. TRANSACTION_POSTED.
    private String action;

    // Type of entity affected, e.g. TRANSACTION.
    private String entityType;

    // ID of the affected entity.
    private Long entityId;

    /*
     * Optional JSON document containing extra details.
     *
     * PostgreSQL stores this field as JSONB.
     *
     * We currently represent it as a JSON-formatted
     * String in Java. Our MyBatis mapper will convert
     * it to JSONB when inserting into PostgreSQL.
     *
     * Example:
     * {"status":"POSTED"}
     */
    private String details;

    // Timestamp generated when the event is inserted.
    private OffsetDateTime createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getBusinessId() {
        return businessId;
    }

    public void setBusinessId(Long businessId) {
        this.businessId = businessId;
    }

    public Long getActorId() {
        return actorId;
    }

    public void setActorId(Long actorId) {
        this.actorId = actorId;
    }

    public String getAction() {
        return action;
    }

    public void setAction(String action) {
        this.action = action;
    }

    public String getEntityType() {
        return entityType;
    }

    public void setEntityType(String entityType) {
        this.entityType = entityType;
    }

    public Long getEntityId() {
        return entityId;
    }

    public void setEntityId(Long entityId) {
        this.entityId = entityId;
    }

    public String getDetails() {
        return details;
    }

    public void setDetails(String details) {
        this.details = details;
    }

    public OffsetDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(OffsetDateTime createdAt) {
        this.createdAt = createdAt;
    }
}
